// Common use: maintaining a sliding window, palindrome checking,
// or any queue that needs fast access at both ends

#include <deque>

vector<int> slidingWindowMax(const vector<int>& arr, int k) {
    deque<int> dq;  // Stores indices in decreasing order of value
    vector<int> result;

    for (int i = 0; i < arr.size(); ++i) {
        // Remove out-of-window indices from front
        if (!dq.empty() && dq.front() <= i - k) {
            dq.pop_front();
        }

        // Remove smaller elements from back (maintain monotonic decreasing)
        while (!dq.empty() && arr[dq.back()] <= arr[i]) {
            dq.pop_back();
        }

        dq.push_back(i);

        // Once the first window is complete, record max
        if (i >= k - 1) {
            result.push_back(arr[dq.front()]);
        }
    }

    return result;
}

